package de.corporate.lc.user.api;
import de.corporate.lc.audit.service.AuditService; import de.corporate.lc.user.service.UserService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/users") public class UserController {private final UserService service;private final AuditService audit;public UserController(UserService s,AuditService a){service=s;audit=a;}@GetMapping public List<UserView> all(){return service.all();}@GetMapping("/assignable")public List<AssignableUser> assignable(){return service.assignable();}@org.springframework.transaction.annotation.Transactional @PostMapping public UserView create(@Valid @RequestBody UserRequest r,Authentication a){UserView u=service.create(r);audit.recordChangeInTransaction(a,"USER_CREATED","USER",u.id(),u.username()+" · "+u.role(),null,AdministrationAuditSnapshot.user(u));return u;}@org.springframework.transaction.annotation.Transactional @PutMapping("/{id}")public UserView update(@PathVariable UUID id,@Valid @RequestBody UserRequest r,Authentication a){String before=AdministrationAuditSnapshot.user(service.get(id));UserView u=service.update(id,r,a.getName());audit.recordChangeInTransaction(a,"USER_UPDATED","USER",id,u.username()+" · "+u.role()+" · "+(u.active()?"aktiv":"gesperrt"),before,AdministrationAuditSnapshot.user(u));return u;}@org.springframework.transaction.annotation.Transactional @DeleteMapping("/{id}")public ResponseEntity<Void> delete(@PathVariable UUID id,Authentication a){String before=AdministrationAuditSnapshot.user(service.get(id));service.delete(id,a.getName());audit.recordChangeInTransaction(a,"USER_DELETED","USER",id,"Benutzer gelöscht",before,null);return ResponseEntity.noContent().build();}}
